using System.Text.Json;
namespace Reforged.Server;
public sealed record RuntimeInteractionNarrativeSmokeResult(bool Passed,int QuestCount,int TextRecordCount,IReadOnlyList<string> Checks,IReadOnlyList<string> Failures){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});}
public static class RuntimeInteractionNarrativeSmokeReport
{
 private sealed class QuestPolicy:IRuntimeQuestPolicy{public IReadOnlyList<RuntimeQuestObjectiveProgress> ResolveObjectives(RuntimeNarrativeDefinition q,string a,DateTimeOffset n)=>new[]{new RuntimeQuestObjectiveProgress("generated-policy-objective",0,1,false,new Dictionary<string,string>())};public IReadOnlyList<RuntimeNarrativeEvent> ResolveRewards(RuntimeNarrativeDefinition q,RuntimeQuestJournalSnapshot j,DateTimeOffset n)=>new[]{new RuntimeNarrativeEvent(Guid.NewGuid().ToString("N"),"generated-policy-reward",j.ActorId,null,q.Id,1,n)};}
 private sealed class DialoguePolicy:IRuntimeDialoguePolicy{public RuntimeDialoguePlan Resolve(RuntimeDialogueRequest r,RuntimeQuestJournalSnapshot j,DateTimeOffset n)=>new(true,null,"generated.text.key",new[]{new RuntimeDialogueChoice("continue","generated.choice.key",null)},new[]{new RuntimeNarrativeEvent(Guid.NewGuid().ToString("N"),"dialogue",r.ActorId,r.SpeakerId,null,0,n)});}
 private sealed class Sink:IRuntimeNarrativeEventSink{public readonly List<RuntimeNarrativeEvent> Events=new();public bool Fail;public void Apply(RuntimeNarrativeEvent e){if(Fail)throw new InvalidOperationException("sink-failure");Events.Add(e);}public void Revert(RuntimeNarrativeEvent e)=>Events.Remove(e);}
 public static RuntimeInteractionNarrativeSmokeResult Run(string root,string world){var checks=new List<string>();var failures=new List<string>();try{var quests=RuntimeNarrativeCatalog.Load(root,world,"quests");var texts=RuntimeNarrativeCatalog.Load(root,world,"events");if(quests.Count>0)checks.Add("quest-catalog");else failures.Add("quest-catalog");if(texts.Count>0)checks.Add("text-catalog");else failures.Add("text-catalog");var qid=JsonDocument.Parse(File.ReadAllText(Path.Combine(ServerDataRootResolver.ResolveDefault(root).DataRoot,"quests.json"))).RootElement.GetProperty("records")[0].GetProperty("id").GetString()!;var journal=new RuntimeQuestJournal("actor.1");var sink=new Sink();var engine=new RuntimeInteractionNarrativeEngine(quests,new QuestPolicy(),new DialoguePolicy(),sink);if(engine.AcceptQuest(journal,qid,DateTimeOffset.UtcNow))checks.Add("accept");else failures.Add("accept");if(journal.ApplyProgress(qid,"generated-policy-objective",1))checks.Add("progress");else failures.Add("progress");var talk=engine.Talk(journal,new("r","actor.1","npc.1",null),DateTimeOffset.UtcNow);if(talk.Succeeded&&talk.Choices.Count==1)checks.Add("dialogue");else failures.Add("dialogue");var done=engine.CompleteQuest(journal,qid,DateTimeOffset.UtcNow);if(done.Succeeded)checks.Add("complete-reward");else failures.Add("complete-reward");var snap=journal.Capture();var restored=new RuntimeQuestJournal("actor.1");restored.Restore(snap);if(restored.Validate(quests).Count==0)checks.Add("persistence-validator");else failures.Add("persistence-validator");var rollbackJournal=new RuntimeQuestJournal("actor.2");engine.AcceptQuest(rollbackJournal,qid,DateTimeOffset.UtcNow);rollbackJournal.ApplyProgress(qid,"generated-policy-objective",1);sink.Fail=true;try{engine.CompleteQuest(rollbackJournal,qid,DateTimeOffset.UtcNow);failures.Add("rollback");}catch{if(rollbackJournal.Capture().Quests.Single().Status==RuntimeQuestStatus.Active)checks.Add("rollback");else failures.Add("rollback");}return new(failures.Count==0,quests.Count,texts.Count,checks,failures);}catch(Exception ex){failures.Add(ex.GetType().Name+":"+ex.Message);return new(false,0,0,checks,failures);}}
}
